import '../models/candle.dart';class I{static double ema(List<double>a,int n){if(a.isEmpty)return 0;var e=a.first,k=2/(n+1);for(final x in a.skip(1))e=x*k+e*(1-k);return e;}static double sma(List<double>a,int n){if(a.isEmpty)return 0;final s=a.length<n?a:a.sublist(a.length-n);return s.reduce((x,y)=>x+y)/s.length;}static double rsi(List<double>a){if(a.length<15)return 50;var g=0.0,l=0.0;for(var i=a.length-14;i<a.length;i++){final d=a[i]-a[i-1];if(d>=0)g+=d;else l-=d;}if(l==0)return 100;final rs=g/l;return 100-100/(1+rs);}static List<double> bb(List<double>a){final m=sma(a,20),s=a.sublist(a.length<20?0:a.length-20);var v=0.0;for(final x in s)v+=(x-m)*(x-m);final sd=(v/s.length);var q=sd>0?sd.sqrt():0;return[m,m+2*q,m-2*q];}static double vwap(List<Candle>a){var p=0.0,v=0.0;for(final c in a){final t=(c.high+c.low+c.close)/3;p+=t*c.volume;v+=c.volume;}return v==0?a.last.close:p/v;}}
extension X on double{double sqrt(){var y=1.0;for(var i=0;i<10;i++)y=(y+this/y)/2;return y;}}
